SIGNALS={
 'APPLICATION_FAILED_TO_START':'APPLICATION FAILED TO START',
 'APPLICATION_RUN_FAILED':'Application run failed',
 'CONTEXT_INITIALIZATION_CANCELLED':'cancelling refresh attempt',
 'PLACEHOLDER_UNRESOLVED':'Could not resolve placeholder',
 'CONNECTION_REFUSED':'Connection refused',
 'PASSWORD_AUTHENTICATION_FAILED':'password authentication failed',
 'PERMISSION_DENIED':'Permission denied',
 'PKIX_VALIDATION_FAILED':'PKIX path building failed',
 'FLYWAY_VALIDATION_FAILED':'Migrations have failed validation',
 'PORT_IN_USE':'Address already in use',
 'OUT_OF_MEMORY':'OutOfMemoryError',
 'CLASS_NOT_FOUND':'ClassNotFoundException',
 'MISSING_BEAN':'could not be found',
 'NO_QUALIFYING_BEAN':'No qualifying bean of type',
}

def summarize(raw):
 text=raw.decode('utf-8','replace')
 lines=text.splitlines(); chain=[]; frames=[]; unknown=0
 for i,line in enumerate(lines,1):
  for m in re.finditer(r'(?<![\w.$])([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*(?:Exception|Error))(?=[:\s]|$)',line):
   name=m.group(1)
   if name in KNOWN['exceptions']:
    item={'line':i,'class':name,'causedBy':'Caused by:' in line}
    if not chain or (chain[-1]['class'],chain[-1]['causedBy'])!=(name,item['causedBy']):chain.append(item)
   else:unknown+=1
  for m in re.finditer(r'\bat (it\.comune\.trieste\.ouf\.[\w.$]+)\([^():]+:(\d{1,6})\)',line):
   cls=m.group(1).rsplit('.',1)[0]
   if cls in KNOWN['classes']:
    item={'class':cls,'sourceLine':int(m.group(2))}
    if item not in frames:frames.append(item)
 def present(values):
  return [v for v in values if re.search(r'(?<![A-Za-z0-9_.-])'+re.escape(v)+r'(?![A-Za-z0-9_.-])',text)]
 beans=[]
 for b in re.findall(r"(?:bean with name|bean named) ['\"]([^'\"]+)['\"]",text):
  if b in KNOWN['beans'] and b not in beans:beans.append(b)
 placeholders=[]
 for p in re.findall(r"Could not resolve placeholder ['\"]([^'\"]+)['\"]",text):
  if p in KNOWN['properties'] and p not in placeholders:placeholders.append(p)
 return {'linesRead':len(lines),'exceptionChain':chain[:50],
  'unknownExceptionOccurrencesOmitted':unknown,'sourceFrames':frames[:30],
  'knownErrorCodes':present(KNOWN['codes']),'knownBeans':beans,
  'unresolvedKnownProperties':placeholders,
  'signals':[k for k,v in SIGNALS.items() if v in text],
  'arbitraryMessagesEmitted':False,'rawLogsEmitted':False,
  'scope':'ALLOWLISTED_SYMBOLS_AND_STATIC_SIGNALS_NOT_COMPLETE_ERROR_TEXT'}

def command(work,label,args):
 out=work/(label+'.stdout.private');err=work/(label+'.stderr.private')
 with out.open('xb') as o,err.open('xb') as e:
  try:code=subprocess.run((*DOCKER,*args),stdout=o,stderr=e,timeout=25).returncode
  except subprocess.TimeoutExpired:code=None
 def tail(p):
  size=p.stat().st_size
  with p.open('rb') as f:
   if size>LIMIT:f.seek(size-LIMIT)
   data=f.read(LIMIT)
  return data,size>LIMIT
 a,at=tail(out);b,bt=tail(err)
 return {'exitCode':code,'truncated':at or bt},a,b

def inspect(work,label,cid):
 result,out,err=command(work,label,('container','inspect',cid))
 if result['exitCode']!=0 or result['truncated']:return {'read':False,**result},None
 try:
  doc=json.loads(out)[0];s=doc['State']
  state={k:s.get(k) for k in ('Running','Paused','Restarting','OOMKilled','Dead','Pid','ExitCode','StartedAt','FinishedAt')}
  # Only typed scalars and RFC3339 times; no State.Error, config or env values.
  for k in ('Running','Paused','Restarting','OOMKilled','Dead'):
   if type(state[k]) is not bool:raise ValueError()
  for k in ('Pid','ExitCode'):
   if type(state[k]) is not int:raise ValueError()
  for k in ('StartedAt','FinishedAt'):
   if not re.fullmatch(r'\d{4}-\d\d-\d\dT[0-9:.]+(?:Z|[+-]\d\d:\d\d)',state[k]):raise ValueError()
  return {'read':True,'exactContainer':doc['Id']==cid,'expectedCandidateImage':doc['Image']==IMAGE,
          'state':state,'engineErrorPresent':bool(s.get('Error'))},state
 except (ValueError,KeyError,IndexError,TypeError):return {'read':False,'reason':'INSPECT_SHAPE_UNEXPECTED'},None

def run(report):
 if os.geteuid()!=0 or not sys.flags.isolated:raise RuntimeError('ISOLATED_ROOT_REQUIRED')
 os.umask(0o077)
 work=Path(tempfile.mkdtemp(prefix='semantic-exit-read-',dir='/var/lib/ouf-storage-migration'))
 report['privateEvidenceDirectory']=str(work)
 report['replacementBefore'],before=inspect(work,'replacement-before',CID)
 report['previousContainer'],_=inspect(work,'previous-container',OLD)
 result,out,err=command(work,'replacement-logs',('logs','--timestamps','--tail','800',CID))
 report['logs']={'read':result['exitCode']==0,**result}
 if result['exitCode']==0:
  # Docker may route stdout and stderr separately; preserve stream provenance.
  report['logs']['stdout']=summarize(out);report['logs']['stderr']=summarize(err)
 report['replacementAfter'],after=inspect(work,'replacement-after',CID)
 report['containerStateUnchangedDuringRead']=before is not None and before==after
 report['journalFilesPresent']={name:(JOURNAL/name).is_file() for name in
  ('created.json','migration-intent.json','migration.stdout.private','application-start-intent.json','complete.json')}
 report['currentReplacementMarkerPresent']=(JOURNAL.parent/'semantic-discovery-current.json').is_file()
 report['status']='SEMANTIC_EXIT_READ_COMPLETE' if result['exitCode']==0 and before is not None and after is not None else 'READ_PARTIAL'
 report['observedAt']=datetime.now(timezone.utc).isoformat()
 (work/'report.json').write_text(json.dumps(report,sort_keys=True)+'\n')

def main():
 report={'schema':'ouf.semantic-application-exit-read.v1','status':'READ_INCOMPLETE',
  'serviceConfigurationChanged':False,'serviceStartDispatched':False,'serviceStops':0,
  'databaseRequests':0,'migrationDispatched':False,'businessRequestsIssued':0,'s3Requests':0,
  'credentialFilesRead':0,'credentialValuesEmitted':False,'rawLogsEmitted':False}
 try:run(report)
 except Exception as e:report['reason']=str(e) if type(e) is RuntimeError and str(e)=='ISOLATED_ROOT_REQUIRED' else type(e).__name__
 print(json.dumps(report,sort_keys=True))
if __name__=='__main__':main()
